import os from "node:os";
import { defineConfig, devices } from "@playwright/test";

/**
 * Playwright configuration for end-to-end tests.
 *
 * Tests run against the Docker Compose stack (Traefik proxy at localhost:80).
 * Chromium only — sufficient for e2e validation.
 *
 * Single project with full parallelism. Each test file is self-contained and
 * creates its own data. Tests that need authenticated sessions create browser
 * contexts with storageState files (generated by global-setup).
 *
 * globalSetup seeds the auth accounts needed for storageState + login tests.
 * Everything else (families, people, wishes) is created per-scenario.
 */
export default defineConfig({
  testDir: "./tests",
  fullyParallel: true,
  forbidOnly: !!process.env.CI,
  retries: process.env.CI ? 2 : 0,
  /* Scale to the machine: more browser workers than cores starve the longest
   * test (core-flow) into its test timeout without speeding the suite up. */
  workers: os.cpus().length,

  /* Timeouts — heavy multi-step flows can approach 30s under full parallel load
   * on an 8-core machine (30s is the untuned Playwright default); 60s keeps
   * headroom while still catching genuine hangs */
  timeout: 60_000,
  expect: { timeout: 10_000 },

  /* Global setup: seed auth accounts + generate storageState files */
  globalSetup: "./helpers/global-setup",

  use: {
    baseURL: "http://localhost",
    trace: "on-first-retry",
    screenshot: "only-on-failure",
    video: "retain-on-failure",
  },

  /* Single project — tests create their own browser contexts with storageState as needed.
   * Run file subsets with: npx playwright test tests/admin-*.spec.ts
   */
  projects: [
    {
      name: "chromium",
      use: { ...devices["Desktop Chrome"] },
    },
  ],

  /* Reporter: list + HTML on failure */
  reporter: [
    ["list"],
    ["html", { outputFolder: "playwright-report", open: "on-failure" }],
  ],
});
